import CryptoKit
import Foundation
import Testing

@testable import IsudoKit

/// Replays the Rust reference's corpus: thousands of generated inputs, many
/// of them damaged or hostile, each with the reference's verdict.
///
/// This implementation is the one a person reads a request on, so it has to
/// agree with the reference on every input, not only the well-formed ones:
/// which bytes are a request at all, what each one says, how every character
/// of it is shown, and which a watch may approve.
///
/// The corpus is `testdata/differential.json`, generated by
/// `crates/sim/src/differential.rs`. `make differential` replays a much
/// larger one, named in `ISUDO_DIFFERENTIAL`.
@Suite struct DifferentialTests {
    let corpus: [String: Any]

    init() throws {
        let file: URL
        if let path = ProcessInfo.processInfo.environment["ISUDO_DIFFERENTIAL"] {
            file = URL(filePath: path)
        } else {
            file = URL(filePath: #filePath)
                .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
                .deletingLastPathComponent().deletingLastPathComponent()
                .appending(path: "testdata/differential.json")
        }
        corpus = try #require(try JSONSerialization.jsonObject(with: Data(contentsOf: file)) as? [String: Any])
    }

    /// Runs `check` on every case of a section. It returns nil for a case
    /// that agrees and a description of the disagreement otherwise. All of
    /// them are counted, and the first few reported.
    private func replay<Case>(_ section: String, as _: Case.Type, minimum: Int, _ check: (Case) throws -> String?) throws {
        let cases = try #require(corpus[section] as? [Case], "no section \(section)")
        #expect(cases.count >= minimum, "\(section) has only \(cases.count) cases")
        var differences: [String] = []
        for (index, entry) in cases.enumerated() {
            if let difference = try check(entry) {
                differences.append("#\(index): \(difference)")
            }
        }
        #expect(
            differences.isEmpty,
            "\(section): \(differences.count) of \(cases.count) cases differ from the reference. \(differences.prefix(5).joined(separator: " | "))"
        )
    }

    private func bytes(_ value: Any?) throws -> Data {
        try Codec.hexDecode(try #require(value as? String))
    }

    /// Text is carried as the hex of its UTF-8: a JSON reader cannot be
    /// trusted with strings this awkward (Foundation's drops a leading
    /// byte-order mark).
    private func text(_ value: Any?) throws -> String {
        try #require(String(validatingUTF8: Array(try bytes(value))))
    }

    private func same(_ ours: String, _ theirs: String) -> Bool {
        // Scalar by scalar: Swift's own string equality treats some
        // different sequences as the same text.
        ours.unicodeScalars.elementsEqual(theirs.unicodeScalars)
    }

    /// Everything shown of a request, as the reference lays it out.
    private func shown(_ request: Request) -> String {
        let display = RequestDisplay(request)
        var lines = [display.host.plain, display.user?.plain ?? "", display.executable.plain, display.workingDirectory.plain]
        lines += display.arguments.map(\.plain)
        lines += display.environment.map { $0.name.plain + "=" + $0.value.plain }
        lines += display.ancestry.map(\.plain)
        return Codec.hexEncode(SHA256.hash(data: Data(lines.joined(separator: "\n").utf8)))
    }

    @Test func requests() throws {
        try replay("requests", as: [String: Any].self, minimum: 400) { entry in
            let input = try bytes(entry["hex"])
            let expected = try #require(entry["ok"] as? Bool)
            guard let request = try? Request.decode(input) else {
                return expected ? "refused a request the reference accepts: \(Codec.hexEncode(input.prefix(24)))…" : nil
            }
            guard expected else { return "accepted bytes the reference refuses: \(Codec.hexEncode(input.prefix(24)))…" }
            if request.encode() != input { return "decoded to something that does not encode back to the same bytes" }
            if request.isSimpleEnough != (entry["simple"] as? Bool) { return "disagrees on whether a watch could approve it" }
            if request.isMarkedForWatch != (entry["marked"] as? Bool) { return "disagrees on the computer's mark" }
            if shown(request) != (entry["shown"] as? String) { return "shows it differently: \(RequestDisplay(request).summary.prefix(60))" }
            return nil
        }
    }

    @Test func delegations() throws {
        try replay("delegations", as: [String: Any].self, minimum: 150) { entry in
            let input = try bytes(entry["hex"])
            let expected = try #require(entry["ok"] as? Bool)
            guard let signed = try? SignedDelegation.decode(input) else {
                return expected ? "refused a delegation the reference accepts" : nil
            }
            guard expected else { return "accepted a delegation the reference refuses, named \(signed.delegation.name.debugDescription)" }
            if signed.encode() != input { return "does not encode back to the same bytes" }
            if !same(signed.delegation.name, try text(entry["name"])) { return "reads the name differently" }
            if String(signed.delegation.notAfter) != (entry["not_after"] as? String) { return "reads the expiry differently" }
            return nil
        }
    }

    @Test func pairingLinks() throws {
        try replay("links", as: [String: Any].self, minimum: 100) { entry in
            let link = try text(entry["text"])
            let expected = try #require(entry["ok"] as? Bool)
            guard let offer = try? PairingOffer(link: link) else {
                return expected ? "refused a link the reference accepts: \(link.debugDescription.prefix(120))" : nil
            }
            guard expected else { return "accepted a link the reference refuses: \(link.debugDescription.prefix(120))" }
            if !same(offer.relayURL, try text(entry["relay"])) { return "reads the relay differently" }
            let name = try text(entry["name"])
            if !same(offer.hostName, name) {
                func scalars(_ text: String) -> String { text.unicodeScalars.map { String($0.value, radix: 16) }.joined(separator: " ") }
                return "reads the computer's name as [\(scalars(offer.hostName))], reference [\(scalars(name))]"
            }
            if offer.pairingID + offer.hostPub + offer.secret + offer.commitment != (try bytes(entry["binary"])) {
                return "reads the keys differently"
            }
            return nil
        }
    }

    @Test func escaping() throws {
        try replay("escape", as: [Any].self, minimum: 300) { entry in
            let input = try bytes(entry.first)
            let expected = try text(entry.last)
            let ours = EscapedText(input).plain
            return same(ours, expected) ? nil : "\(Codec.hexEncode(input)) shown as \(ours.debugDescription), reference \(expected.debugDescription)"
        }
    }

    @Test func riskyVariableNames() throws {
        try replay("env_risk", as: [Any].self, minimum: 100) { entry in
            let name = try bytes(entry.first)
            let expected = try #require(entry.last as? Bool)
            return EnvRisk.isRisky(name) == expected
                ? nil : "\(String(decoding: name, as: UTF8.self).debugDescription) (\(Codec.hexEncode(name))) should be risky=\(expected)"
        }
    }

    @Test func hexAndBase64() throws {
        try replay("hex", as: [Any].self, minimum: 100) { entry in
            let input = try text(entry.first)
            let expected = entry.last as? String
            let ours = (try? Codec.hexDecode(input)).map { Codec.hexEncode($0) }
            return ours == expected ? nil : "hex \(input.debugDescription): \(ours ?? "refused"), reference \(expected ?? "refused")"
        }
        try replay("b64", as: [Any].self, minimum: 100) { entry in
            let input = try text(entry.first)
            let expected = entry.last as? String
            let ours = (try? Codec.b64Decode(input)).map { Codec.hexEncode($0) }
            return ours == expected ? nil : "base64 \(input.debugDescription): \(ours ?? "refused"), reference \(expected ?? "refused")"
        }
    }

    @Test func watchNames() throws {
        try replay("names", as: [Any].self, minimum: 150) { entry in
            let name = try text(entry.first)
            let expected = try #require(entry.last as? Bool)
            return Delegation.isValid(name: name) == expected ? nil : "\(name.debugDescription) should be valid=\(expected)"
        }
    }

    @Test func denialReasonsAreCutAtTheSamePlace() throws {
        try replay("reasons", as: [Any].self, minimum: 60) { entry in
            let reason = try text(entry.first)
            let expected = try text(entry.last)
            let ours = Pairing.clip(reason: reason)
            return same(ours, expected) ? nil : "cut to \(ours.utf8.count) bytes, reference \(expected.utf8.count)"
        }
    }

    @Test func pairingCodes() throws {
        try replay("codes", as: [String: Any].self, minimum: 50) { entry in
            var rest = try bytes(entry["inputs"])
            func take(_ count: Int) -> Data {
                defer { rest = rest.dropFirst(count) }
                return Data(rest.prefix(count))
            }
            let secret = take(32)
            let parties = Crypto.Parties(pairingID: take(16), hostPub: take(65), phoneSignPub: take(65), phoneKemPub: take(65))
            let (hostNonce, phoneNonce) = (take(16), take(16))
            let name = try text(entry["name"])
            if Crypto.confirmationCode(secret: secret, parties: parties, hostNonce: hostNonce, phoneNonce: phoneNonce)
                != (entry["code"] as? String) { return "a different six-digit code" }
            if Crypto.claimMAC(secret: secret, parties: parties, phoneNonce: phoneNonce, phoneName: name) != (try bytes(entry["mac"])) {
                return "a different claim MAC for the name \(name.debugDescription)"
            }
            if Crypto.commitment(pairingID: parties.pairingID, hostPub: parties.hostPub, hostNonce: hostNonce)
                != (try bytes(entry["commitment"])) { return "a different commitment" }
            return nil
        }
    }

    @Test func everySectionIsReplayed() {
        let known: Set = ["about", "requests", "delegations", "links", "escape", "env_risk", "hex", "b64", "names", "reasons", "codes"]
        #expect(Set(corpus.keys) == known)
    }
}
